public static final void toByteArray(MessageNano messageObj, byte[] bufferData, int startPos, int spanSize) {
        try {
            final CodedOutputByteBufferNano writerBuffer =
                CodedOutputByteBufferNano.newInstance(bufferData, startPos, spanSize);
            messageObj.writeTo(writerBuffer);
            writerBuffer.checkNoSpaceLeft();
        } catch (IOException ioErr) {
            throw new RuntimeException("Serializing to a byte array threw an IOException "
                    + "(should never happen).", ioErr);
        }
    }

public static final <T extends MessageNano> T combineFrom(T messageObj, final byte[] payload,
            final int offset, final int length) throws InvalidProtocolBufferNanoException {
        try {
            final CodedInputByteBufferNano bufferInput =
                CodedInputByteBufferNano.newInstance(payload, offset, length);
            messageObj.combineFrom(bufferInput);
            bufferInput.checkLastTagWas(0);
            return messageObj;
        } catch (InvalidProtocolBufferNanoException ex) {
            throw ex;
        } catch (IOException ex) {
            throw new RuntimeException("Reading from a byte array threw an IOException (should "
                    + "never happen).");
        }
    }

