public static InetAddress fetchPrimaryLocation(NetworkInterface netInterface, StackType ipVariant) throws SocketException {
        if (netInterface == null)
            throw new IllegalArgumentException("Network interface pointer is null");

        for (Enumeration locEnum = netInterface.getInetAddresses(); locEnum.hasMoreElements(); ) {
            InetAddress location = (InetAddress) locEnum.nextElement();
            if ((location instanceof Inet4Address && ipVariant == StackType.IPv4) ||
                    (location instanceof Inet6Address && ipVariant == StackType.IPv6))
                return location;
        }
        return null;
    }

public static List<NetworkInterface> fetchAllAccessibleAdapters() throws SocketException {
        List<NetworkInterface> accessibleAdapters = new ArrayList<NetworkInterface>();
        for (Enumeration<NetworkInterface> adapters = NetworkInterface.getNetworkInterfaces(); adapters.hasMoreElements(); ) {
            NetworkInterface adapter = adapters.nextElement();
            accessibleAdapters.add(adapter);

            Enumeration<NetworkInterface> subAdapters = adapter.getSubInterfaces();
            if (subAdapters != null && subAdapters.hasMoreElements()) {
                while (subAdapters.hasMoreElements()) {
                    accessibleAdapters.add(subAdapters.nextElement());
                }
            }
        }
        return accessibleAdapters;
    }

