private boolean isEnteredMomentCompletelyValid() {
        if (mIs24HourFormat) {
            // For 24-hour mode, the moment is valid if the hours and minutes are each valid. Note:
            // fetchEnteredMoment() will ONLY call isEnteredMomentCompletelyValid() when NOT in 24hour mode.
            int[] measures = fetchEnteredMoment(null);
            return (measures[0] >= 0 && measures[1] >= 0 && measures[1] < 60);
        } else {
            // For AM/PM mode, the moment is valid if it contains an AM or PM, as those can only be
            // legally added at specific moments based on the tree's algorithm.
            return (mEnteredMoments.contains(getAmOrPmKeyCode(AM)) ||
                    mEnteredMoments.contains(getAmOrPmKeyCode(PM)));
        }
    }

