default <T> ActionContext<T> plan(final Action<T> activity, final T performer) {
	if (isStopped()) {
	    return Actions.emptyActionContext(); // Case of post cancel scheduling
	}

	final SchedulableActionContext<T> scenario = newContext(activity);
	scenario.setActor(performer);
	scenario.schedule();

	return unschedulableActionContext(scenario); // Don't allow for mutation (it's running)
    }
